const n=[{type:"Advanced Passives: 'It is said that'",vnExamples:["Người ta nói rằng anh ấy rất thông minh.","Người ta cho rằng cuốn sách này rất thú vị.","Người ta tin rằng cô ấy đã chuyển đến thành phố khác."],usages:[{title:"Cấu trúc",contents:[{point:"'It is said that' + mệnh đề",examples:["It is said that he is very intelligent.","It is believed that she has moved to another city."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để nói về những ý kiến, niềm tin hoặc thông tin mà nhiều người cho là đúng, thường không rõ nguồn gốc cụ thể.",examples:["It is said that this book is very interesting."]}]}]},{type:"Advanced Passives: 'Have something done'",vnExamples:["Tôi vừa mới sửa xe xong.","Cô ấy thường cắt tóc ở tiệm gần nhà.","Họ đã lắp đặt một hệ thống camera mới."],usages:[{title:"Cấu trúc",contents:[{point:"S + have + something + V3/ed",examples:["I had my car repaired.","She has her hair cut."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để diễn tả hành động mà bạn nhờ hoặc thuê ai đó làm cho mình.",examples:["They had a new camera system installed."]}]}]},{type:"Connectives: 'Much as'",vnExamples:["Dù tôi thích món này, tôi không thể ăn vì tôi đang ăn kiêng.","Dù cô ấy rất cố gắng, cô ấy không đạt được mục tiêu.","Dù chúng tôi thích bộ phim, chúng tôi nghĩ nó hơi dài."],usages:[{title:"Cấu trúc",contents:[{point:"'Much as' + mệnh đề",examples:["Much as I like this dish, I can’t eat it.","Much as she tried, she didn’t achieve her goal."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để diễn tả sự mâu thuẫn giữa hai ý tưởng, thường mang ý nghĩa 'mặc dù'.",examples:["Much as we enjoyed the movie, we thought it was a bit too long."]}]}]},{type:"Connectives: 'As if'",vnExamples:["Anh ấy nói chuyện như thể anh ấy là một chuyên gia.","Cô ấy nhìn tôi như thể tôi đã làm điều gì sai.","Họ hành động như thể họ biết mọi thứ."],usages:[{title:"Cấu trúc",contents:[{point:"'As if' + mệnh đề",examples:["He talks as if he were an expert.","She looked at me as if I had done something wrong."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để diễn tả một điều gì đó có vẻ đúng hoặc để so sánh một cách không thực tế.",examples:["They act as if they know everything."]}]}]},{type:"Connectives: 'Even if'",vnExamples:["Ngay cả khi trời mưa, tôi vẫn sẽ đi chạy.","Ngay cả khi bạn xin lỗi, cô ấy có thể sẽ không tha thứ.","Ngay cả khi chúng ta bắt đầu ngay bây giờ, chúng ta có thể không kịp hoàn thành."],usages:[{title:"Cấu trúc",contents:[{point:"'Even if' + mệnh đề",examples:["Even if it rains, I will go running.","Even if you apologize, she may not forgive you."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để nhấn mạnh rằng một điều gì đó sẽ xảy ra hoặc đúng ngay cả khi có điều kiện khác.",examples:["Even if we start now, we might not finish in time."]}]}]},{type:"Phrase: 'No matter what'",vnExamples:["Dù chuyện gì xảy ra, tôi sẽ luôn ở bên bạn.","Dù anh ấy nói gì, tôi cũng sẽ không thay đổi quyết định.","Dù điều kiện khó khăn thế nào, chúng tôi sẽ không bỏ cuộc."],usages:[{title:"Cấu trúc",contents:[{point:"'No matter what' + mệnh đề",examples:["No matter what happens, I will always stand by you.","No matter what he says, I won’t change my decision."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để nhấn mạnh rằng hành động hoặc kết quả không thay đổi dù bất kỳ tình huống hoặc điều kiện nào xảy ra.",examples:["No matter what the difficulties are, we won’t give up."]}]}]},{type:"Phrase: 'Just a matter of + Noun'",vnExamples:["Đó chỉ là vấn đề thời gian.","Thành công chỉ là vấn đề nỗ lực và kiên nhẫn.","Chiến thắng chỉ là vấn đề thực hành nhiều hơn."],usages:[{title:"Cấu trúc",contents:[{point:"'Just a matter of' + danh từ",examples:["It’s just a matter of time.","It’s just a matter of effort and patience."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để diễn tả rằng điều gì đó sẽ xảy ra hoặc đạt được, phụ thuộc vào một yếu tố cụ thể.",examples:["Winning is just a matter of practicing more."]}]}]},{type:"Cleft Sentences: 'It'",vnExamples:["Chính cô ấy là người đã giúp tôi.","Chính vào ngày hôm qua, chúng tôi gặp nhau.","Chính ngôi nhà này, tôi muốn mua."],usages:[{title:"Cấu trúc",contents:[{point:"It + be + thành phần được nhấn mạnh + mệnh đề",examples:["It was she who helped me.","It was yesterday that we met."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để nhấn mạnh một thành phần trong câu, như chủ ngữ, tân ngữ hoặc trạng ngữ.",examples:["It is this house that I want to buy."]}]}]},{type:"Cleft Sentences: 'What'",vnExamples:["Điều tôi cần là một cuốn sách.","Điều cô ấy nói làm tôi ngạc nhiên.","Điều chúng tôi muốn là hòa bình."],usages:[{title:"Cấu trúc",contents:[{point:"'What' + mệnh đề + be + thành phần được nhấn mạnh",examples:["What I need is a book.","What she said surprised me."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để nhấn mạnh điều gì đó cụ thể, thường là nội dung hoặc ý tưởng trong câu.",examples:["What we want is peace."]}]}]},{type:"Inversion: Negative Adverbials",vnExamples:["Hiếm khi tôi thấy một bộ phim hay như vậy.","Không bao giờ anh ấy nói dối.","Chỉ khi cô ấy rời đi, tôi mới nhận ra sai lầm của mình."],usages:[{title:"Cấu trúc",contents:[{point:"Negative adverbial + auxiliary verb + S + main verb",examples:["Rarely have I seen such a good movie.","Never does he lie."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để nhấn mạnh và tạo hiệu ứng trang trọng trong câu bắt đầu bằng trạng từ phủ định.",examples:["Only when she left did I realize my mistake."]}]}]},{type:"Inversion: 'Little', 'No sooner', and 'Not'",vnExamples:["Ít ai biết rằng anh ấy đã giúp đỡ chúng tôi rất nhiều.","Ngay khi chúng tôi đến nơi, trời bắt đầu mưa.","Không phải tôi không muốn giúp bạn, mà là tôi không có thời gian."],usages:[{title:"Cấu trúc",contents:[{point:"'Little/No sooner/Not' + auxiliary verb + S + main verb",examples:["Little did they know how much he helped us.","No sooner had we arrived than it started raining."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng 'Little' để nhấn mạnh điều bất ngờ, 'No sooner' để diễn tả hành động xảy ra ngay lập tức sau một hành động khác, và 'Not' để nhấn mạnh sự phủ định.",examples:["Not only do I support you, but I also admire your courage."]}]}]},{type:"Present Participle Clauses",vnExamples:["Nhìn thấy cô ấy, anh ấy mỉm cười.","Không biết phải làm gì, chúng tôi chờ đợi sự giúp đỡ.","Lái xe quá nhanh, anh ấy đã bị phạt."],usages:[{title:"Cấu trúc",contents:[{point:"V-ing + phần còn lại của câu",examples:["Seeing her, he smiled.","Driving too fast, he was fined."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để diễn tả hai hành động xảy ra cùng lúc, hoặc một hành động là nguyên nhân của hành động khác.",examples:["Not knowing what to do, we waited for help."]}]}]},{type:"Past Participle Clauses",vnExamples:["Được xây dựng vào năm 1990, tòa nhà này là biểu tượng của thành phố.","Mệt mỏi vì làm việc cả ngày, cô ấy đi ngủ sớm.","Được yêu thích bởi nhiều người, bộ phim đã trở thành một hit lớn."],usages:[{title:"Cấu trúc",contents:[{point:"V3/ed + phần còn lại của câu",examples:["Built in 1990, this building is a city landmark.","Tired from working all day, she went to bed early."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để cung cấp thông tin bổ sung về chủ ngữ, hoặc diễn tả hành động đã xảy ra trước trong câu.",examples:["Loved by many, the movie became a big hit."]}]}]},{type:"Perfect Participle Clauses",vnExamples:["Hoàn thành công việc, cô ấy nghỉ ngơi.","Sau khi bị mắng, cậu bé rời khỏi phòng.","Đã học xong bài, tôi quyết định đi dạo."],usages:[{title:"Cấu trúc",contents:[{point:"Having + V3/ed + phần còn lại của câu",examples:["Having finished her work, she took a rest.","Having been scolded, the boy left the room."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để diễn tả một hành động đã hoàn thành trước một hành động khác trong câu.",examples:["Having studied the lesson, I decided to go for a walk."]}]}]},{type:"Reduced Relative Clauses",vnExamples:["Người đứng ở góc kia là giáo viên của tôi.","Quyển sách được viết bởi một tác giả nổi tiếng rất thú vị.","Những học sinh nộp bài sớm sẽ được điểm cộng."],usages:[{title:"Cấu trúc",contents:[{point:"Danh từ + (V-ing/V3/ed)",examples:["The person standing in the corner is my teacher.","The book written by a famous author is fascinating."]}]},{title:"Cách sử dụng",contents:[{point:"Dùng để rút gọn mệnh đề quan hệ nhằm làm câu ngắn gọn và súc tích hơn.",examples:["Students submitting their work early will get bonus points."]}]}]}];export{n as a};
